<div class="toolbar" data-bind="attr: { id: id }">
    <div class="toolbar-container" data-bind="style: { visibility: showToolbar() ? 'visible' : 'hidden' },
        css: { 'regular': itemSize() === 'regular', 'small': itemSize() === 'small' }">
        <!-- ko foreach: toolbarItems -->

        <div class="toolbar-item" data-bind="visible: visible, attr: { id: id }">
            <!-- ko if: type === "action" -->
            <button class="toolbar-button" data-bind="
                hasFocus: focused,
                attr: { id: id + '-button', title: description, 'aria-label': label },
                event: { mousedown: onClick, keydown: onKeyDown },
                enable: enabled,
                style: { 'max-width': size + 'px' }">
                <div class="toolbar-button-content">
                    <div class="toolbar-button-icon">
                        <se-icon params="with: { name: icon }"></se-icon>
                    </div>
                    <div class="toolbar-button-text" data-bind="text: label"></div>
                </div>
            </button>
            <!-- /ko -->

            <!-- ko if: type === "toggle" -->
            <button class="toolbar-button toggle-button" data-bind="
                hasFocus: focused,
                attr: { id: id + '-button', title: displayDescription, 'aria-label': label },
                event: { mousedown: onClick, keydown: onKeyDown },
                enable: enabled,
                css: { 'toggle-checked': checked },
                style: { 'max-width': size + 'px' }">
                <div class="toolbar-button-content">
                    <div class="toolbar-button-icon">
                        <se-icon params="with: { name: icon }"></se-icon>
                    </div>
                    <div class="toolbar-button-text" data-bind="text: displayLabel"></div>
                </div>
            </button>
            <!-- /ko -->

            <!-- ko if: type === "dropdown" -->
            <!-- ko ifnot: defaultAction === undefined -->
            <!-- ko with: defaultAction -->
            <button class="toolbar-button split-button split-button-left" data-bind="
                hasFocus: focused,
                attr: { id: $parent.id + '-primary-button', title: description, 'aria-label': label },
                event: { mousedown: onClick, keydown: onKeyDown },
                enable: enabled,
                style: { 'max-width': size + 'px' }">
                <div class="toolbar-button-content">
                    <div class="toolbar-button-icon">
                        <se-icon params="with: { name: icon || $parent.icon }"></se-icon>
                    </div>
                    <div class="toolbar-button-text" data-bind="text: $parent.label"></div>
                </div>
            </button>
            <!-- /ko -->
            <button role="menu" class="toolbar-button split-button split-button-right" data-bind="
                hasFocus: focused,
                attr: { id: id + '-secondary-button', title: description, 'aria-label': label },
                event: { mousedown: onClick, keydown: onKeyDown },
                enable: enabled">
                <div class="toolbar-button-content">
                    <div class="toolbar-button-icon">
                        <se-icon params="with: { name: 'CaretDownSolid' }"></se-icon>
                    </div>
                </div>
            </button>
            <!-- /ko -->
            <!-- ko if: defaultAction === undefined -->
            <button role="menu" class="toolbar-button dropdown-button" data-bind="
                hasFocus: focused,
                attr: { id: id + '-button', title: description, 'aria-label': label },
                event: { mousedown: onClick, keydown: onKeyDown },
                enable: enabled,
                style: { 'max-width': size + 'px' }">
                <div class="toolbar-button-content">
                    <div class="toolbar-button-icon">
                        <se-icon params="with: { name: icon }"></se-icon>
                    </div>
                    <div class="toolbar-button-text" data-bind="text: label"></div>
                    <!-- ko if: showDropdownIcon -->
                    <div class="toolbar-button-dropdown">
                        <se-icon params="with: { name: 'CaretDownSolid' }"></se-icon>
                    </div>
                    <!-- /ko -->
                </div>
            </button>
            <!-- /ko -->
            <!-- /ko -->

            <!-- ko if: type === "separator" -->
            <div class="toolbar-separator"></div>
            <!-- /ko -->
        </div>
        <!-- /ko -->
    </div>
</div>
